/* A geometric 3D product illustration: extruded meshes, perspective camera,
   directional lighting, depth sorting, and an animated folding pivot. */
(()=>{'use strict';const canvas=document.getElementById('knifeCanvas'),ctx=canvas.getContext('2d');if(!ctx)return;let w=0,h=0,yaw=.35,pitch=-.48,fold=0,target=0,color='#f76b22',drag=false,lastX=0,lastY=0,auto=!matchMedia('(prefers-reduced-motion: reduce)').matches,tick=0;const motion=matchMedia('(prefers-reduced-motion: reduce)');
const handle=[[-1.8,-.39],[-1.68,-.52],[-1.38,-.56],[.98,-.56],[1.19,-.43],[1.23,-.24],[1.08,-.18],[.92,-.06],[.86,.08],[.9,.22],[1.13,.36],[1.16,.51],[-1.6,.51],[-1.78,.37]];
const blade=[[0,-.3],[.24,-.34],[.39,-.27],[.5,-.34],[.61,-.24],[.72,-.31],[.83,-.2],[.94,-.26],[1.05,-.14],[1.16,-.18],[1.34,-.09],[1.64,.09],[1.93,.31],[2.15,.5],[1.73,.46],[1.22,.4],[.64,.33],[0,.29]];
function mesh(poly,z1,z2,kind){const faces=[];faces.push({v:poly.map(p=>[p[0],p[1],z1]),normal:[0,0,-1],kind});faces.push({v:poly.map(p=>[p[0],p[1],z2]),normal:[0,0,1],kind});for(let i=0;i<poly.length;i++){const a=poly[i],b=poly[(i+1)%poly.length],dx=b[0]-a[0],dy=b[1]-a[1],len=Math.hypot(dx,dy);faces.push({v:[[...a,z1],[...b,z1],[...b,z2],[...a,z2]],normal:[dy/len,-dx/len,0],kind})}return faces}
const body=[...mesh(handle,-.27,-.1,'handle'),...mesh(handle,.1,.27,'handle')],edge=mesh(blade,-.08,.08,'blade');
function pivotPoint(p){const a=-fold*Math.PI;return [p[0]*Math.cos(a)-p[1]*Math.sin(a)+.94,p[0]*Math.sin(a)+p[1]*Math.cos(a),p[2]]}
function transform(p,normal=false){let x=p[0]-(normal?0:.55),y=p[1],z=p[2];const c=Math.cos(yaw),s=Math.sin(yaw);[x,z]=[x*c+z*s,-x*s+z*c];const cp=Math.cos(pitch),sp=Math.sin(pitch);[y,z]=[y*cp-z*sp,y*sp+z*cp];const angle=-.48;return [x*Math.cos(angle)-y*Math.sin(angle),x*Math.sin(angle)+y*Math.cos(angle),z]}
function project(p){const scale=Math.min(w/6.2,h/4.7)*8/(8+p[2]);return [w/2+p[0]*scale,h*.48+p[1]*scale]}
function shade(n,kind){const rgb=color.match(/\w\w/g).map(x=>parseInt(x,16));const dot=n[0]*-.25+n[1]*-.7+n[2]*.65;const light=Math.max(.45,Math.min(1.15,.78+dot*.34));return `rgb(${rgb.map(x=>Math.min(255,Math.round(x*light+(kind==='blade'?4:0)))).join(',')})`}
function circle3D(cx,cy,z,r,kind){const points=Array.from({length:28},(_,i)=>{const a=i*Math.PI*2/28;return [cx+Math.cos(a)*r,cy+Math.sin(a)*r,z]});return mesh(points.map(p=>p.slice(0,2)),z,z+.045,kind)}
const pin=circle3D(.94,0,.28,.13,'handle'),endPin=circle3D(-1.52,0,.28,.07,'handle');
function draw(){ctx.clearRect(0,0,w,h);const grad=ctx.createRadialGradient(w*.51,h*.69,0,w*.51,h*.69,w*.36);grad.addColorStop(0,'#79684928');grad.addColorStop(1,'#79684900');ctx.save();ctx.translate(0,h*.52);ctx.scale(1,.25);ctx.fillStyle=grad;ctx.fillRect(0,0,w,h*2);ctx.restore();const faces=[...body,...edge.map(f=>({...f,v:f.v.map(pivotPoint),normal:[f.normal[0]*Math.cos(-fold*Math.PI)-f.normal[1]*Math.sin(-fold*Math.PI),f.normal[0]*Math.sin(-fold*Math.PI)+f.normal[1]*Math.cos(-fold*Math.PI),f.normal[2]]})),...pin,...endPin,...circle3D(.94,0,-.33,.13,'handle'),...circle3D(-1.52,0,-.33,.07,'handle')].map(f=>({...f,v:f.v.map(p=>transform(p)),n:transform(f.normal,true)}));faces.sort((a,b)=>b.v.reduce((s,p)=>s+p[2],0)/b.v.length-a.v.reduce((s,p)=>s+p[2],0)/a.v.length);for(const f of faces){const pts=f.v.map(project);ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.fillStyle=shade(f.n,f.kind);ctx.fill();ctx.strokeStyle='#af410b22';ctx.lineWidth=.5;ctx.stroke();if(f.v.length>6){ctx.save();ctx.clip();ctx.strokeStyle='#ffffff09';ctx.lineWidth=.7;for(let y=0;y<h;y+=3){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y-70);ctx.stroke()}ctx.restore()}}}
function resize(){const box=canvas.getBoundingClientRect();w=box.width;h=box.height;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);draw()}new ResizeObserver(resize).observe(canvas);
let last=0;function frame(time){const dt=Math.min(40,time-last||16);last=time;if(auto&&!drag){tick+=dt*.0004;yaw=.38+Math.sin(tick)*.35}if(motion.matches)fold=target;else fold+=(target-fold)*Math.min(1,dt*.006);if(document.visibilityState==='visible')draw();requestAnimationFrame(frame)}requestAnimationFrame(frame);
const rotate=document.getElementById('rotateButton');function rotationState(){rotate.textContent=auto?'Ⅱ':'▷';rotate.setAttribute('aria-label',auto?'Pause rotation':'Resume rotation');rotate.setAttribute('aria-pressed',String(auto))}rotationState();rotate.onclick=()=>{auto=!auto;rotationState()};document.getElementById('foldButton').onclick=e=>{target=target?0:1;const b=e.currentTarget;b.innerHTML=target?'Click to open <span>↔</span>':'Click to fold <span>↔</span>';b.setAttribute('aria-pressed',String(!!target))};canvas.onpointerdown=e=>{drag=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!drag)return;auto=false;rotationState();yaw+=(e.clientX-lastX)*.012;pitch=Math.max(-1.2,Math.min(1.2,pitch+(e.clientY-lastY)*.008));lastX=e.clientX;lastY=e.clientY};canvas.onpointerup=canvas.onpointercancel=()=>drag=false;canvas.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();auto=false;rotationState();yaw+=(e.key==='ArrowLeft'?-.12:e.key==='ArrowRight'?.12:0);pitch+=(e.key==='ArrowUp'?-.12:e.key==='ArrowDown'?.12:0)}};window.setKnifeColor=c=>{color=c};})();
